mapper.select:
SELECT R.SCHEDULE_DATE, /*排产日期*/ null CD90_BATCH_NO, R.CX_BATCH_NO, /*成型批次号*/ CI.CORD_SPEC BIG_ROLL_CODE, /*帘线规格*/ NVL(ROUND(SUM((nvl(R.CLASS1_PLAN_QTY, 0) + nvl(R.CLASS2_PLAN_QTY, 0) + nvl(R.CLASS3_PLAN_QTY, 0)) * CI.SIDEWALL_LENGTH / 1000 * (NVL(CI.TIRE_FABRIC_CRAFT1, 0) + NVL(CI.TIRE_FABRIC_CRAFT2, 0) + NVL(CI.TIRE_FABRIC_CRAFT3, 0)) / 1000 / #{breadth}), 6), 0) DAY_PLAN_QTY, /*中班计划量*/ NVL(ROUND(SUM((nvl(R.CLASS4_PLAN_QTY, 0) + nvl(R.CLASS5_PLAN_QTY, 0)) * CI.SIDEWALL_LENGTH / 1000 * (NVL(CI.TIRE_FABRIC_CRAFT1, 0) + NVL(CI.TIRE_FABRIC_CRAFT2, 0) + NVL(CI.TIRE_FABRIC_CRAFT3, 0)) / 1000 / #{breadth}), 6), 0) NIGHT_PLAN_QTY, /*夜班计划量*/ NVL(CEIL(SUM(R.CLASS1_PLAN_QTY * (NVL(CI.TIRE_FABRIC_CRAFT1, 0) + NVL(CI.TIRE_FABRIC_CRAFT2, 0) + NVL(CI.TIRE_FABRIC_CRAFT3, 0)) * CI.SIDEWALL_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS1_PLAN, NVL(CEIL(SUM(R.CLASS2_PLAN_QTY * (NVL(CI.TIRE_FABRIC_CRAFT1, 0) + NVL(CI.TIRE_FABRIC_CRAFT2, 0) + NVL(CI.TIRE_FABRIC_CRAFT3, 0)) * CI.SIDEWALL_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS2_PLAN, NVL(CEIL(SUM(R.CLASS3_PLAN_QTY * (NVL(CI.TIRE_FABRIC_CRAFT1, 0) + NVL(CI.TIRE_FABRIC_CRAFT2, 0) + NVL(CI.TIRE_FABRIC_CRAFT3, 0)) * CI.SIDEWALL_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS3_PLAN, NVL(CEIL(SUM(R.CLASS4_PLAN_QTY * (NVL(CI.TIRE_FABRIC_CRAFT1, 0) + NVL(CI.TIRE_FABRIC_CRAFT2, 0) + NVL(CI.TIRE_FABRIC_CRAFT3, 0)) * CI.SIDEWALL_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS4_PLAN, NVL(CEIL(SUM(R.CLASS5_PLAN_QTY * (NVL(CI.TIRE_FABRIC_CRAFT1, 0) + NVL(CI.TIRE_FABRIC_CRAFT2, 0) + NVL(CI.TIRE_FABRIC_CRAFT3, 0)) * CI.SIDEWALL_LENGTH / 1000 / 1000 / #{breadth})), 0) CX_CLASS5_PLAN, CI.ORIGINAL_LINE_CODE ORIGINAL_LINE_CODE, '0' DATA_SOURCE /* 成型来的排程数据来源默认自动排产 */ FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE1 IS NOT NULL
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
GROUP BY R.SCHEDULE_DATE, R.CX_BATCH_NO, CI.CORD_SPEC, CI.ORIGINAL_LINE_CODE HAVING SUM((NVL(R.CLASS1_PLAN_QTY, 0) + NVL(R.CLASS2_PLAN_QTY, 0) + NVL(R.CLASS3_PLAN_QTY, 0) + NVL(R.CLASS4_PLAN_QTY, 0) + NVL(R.CLASS5_PLAN_QTY, 0)) * CI.SIDEWALL_LENGTH * (NVL(CI.TIRE_FABRIC_CRAFT1, 0) + NVL(CI.TIRE_FABRIC_CRAFT2, 0) + NVL(CI.TIRE_FABRIC_CRAFT3, 0)) ) != 0

SELECT CI.EMBRYO_CODE, CI.SIDEWALL_LENGTH, CI.CORD_SPEC, CI.TIRE_FABRIC_CODE1, CI.TIRE_FABRIC_CRAFT1, CI.TIRE_FABRIC_CODE2, CI.TIRE_FABRIC_CRAFT2, CI.TIRE_FABRIC_CODE3, CI.TIRE_FABRIC_CRAFT3 FROM T_PRODUCT_CONSTRUCTION_INFO CI WHERE CI.DEL_FLAG = '0'
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
AND EXISTS (SELECT 1 FROM T_CX_SCHEDULE_RESULT R WHERE R.schedule_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION)

WITH temp_tab_BIG_ROLL_CODE AS (
SELECT #{bigRollCode} big_roll_code FROM dual
) SELECT BIG_ROLL_CODE, CEIL(SUM(SINGLE_SHIFT_LH_QTY * 3 * SIDEWALL_LENGTH * TIRE_FABRIC_CRAFT) / #{breadth}) DAY_USED /*日用参考量*/ FROM ( SELECT CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE1 CLOTH_CODE, /*1#胎体布编号*/ nvl(R.SINGLE_SHIFT_LH_QTY, 0) SINGLE_SHIFT_LH_QTY, /*单班硫化产量*/ nvl(CI.SIDEWALL_LENGTH / 1000, 0) SIDEWALL_LENGTH, /*单耗，单位换毫米换算成米*/ nvl(CI.TIRE_FABRIC_CRAFT1 / 1000, 0) TIRE_FABRIC_CRAFT /*工艺，单位换毫米换算成米*/ FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON CI.EMBRYO_CODE = R.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND REGEXP_LIKE(TRIM(CI.TIRE_FABRIC_CRAFT1), '(^[+-]?\d{0,}\.?\d{0,}$)') /*排除非数字字符串*/ UNION ALL SELECT CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE2 CLOTH_CODE, /*2#胎体布编号*/ nvl(R.SINGLE_SHIFT_LH_QTY, 0) SINGLE_SHIFT_LH_QTY, /*单班硫化产量*/ nvl(CI.SIDEWALL_LENGTH / 1000, 0) SIDEWALL_LENGTH, /*单耗*/ nvl(CI.TIRE_FABRIC_CRAFT2 / 1000, 0) TIRE_FABRIC_CRAFT /*工艺*/ FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON CI.EMBRYO_CODE = R.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE2 IS NOT NULL AND REGEXP_LIKE(TRIM(CI.TIRE_FABRIC_CRAFT2), '(^[+-]?\d{0,}\.?\d{0,}$)') UNION ALL SELECT CORD_SPEC BIG_ROLL_CODE, CI.TIRE_FABRIC_CODE3 CLOTH_CODE, /*3#胎体布编号*/ nvl(R.SINGLE_SHIFT_LH_QTY, 0) SINGLE_SHIFT_LH_QTY, /*单班硫化产量*/ (CI.SIDEWALL_LENGTH / 1000) SIDEWALL_LENGTH, /*单耗*/ (CI.TIRE_FABRIC_CRAFT3 / 1000) TIRE_FABRIC_CRAFT /*工艺*/ FROM T_CX_SCHEDULE_RESULT R LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON CI.EMBRYO_CODE = R.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE3 IS NOT NULL AND REGEXP_LIKE(TRIM(CI.TIRE_FABRIC_CRAFT3), '(^[+-]?\d{0,}\.?\d{0,}$)') ) WHERE BIG_ROLL_CODE IN ( SELECT big_roll_code FROM temp_tab_BIG_ROLL_CODE ) GROUP BY BIG_ROLL_CODE

mapper.insert:
INSERT INTO T_XWYY_SCHEDULE_RESULT (ID, schedule_DATE, CD90_BATCH_NO, BATCH_NO, ORDER_NO, BIG_ROLL_CODE, ORIGINAL_LINE_CODE, ORIGINAL_LINE_QTY_NUM, MACHINE_ID, DAY_PLAN_QTY, DAY_PLAN_QTY_NUM, DAY_FINISH_QTY, DAY_SYS_ANALYSIS, DAY_HAND_ANALYSIS, DAY_PROCESS_VALUE, NIGHT_PLAN_QTY, NIGHT_PLAN_QTY_NUM, NIGHT_FINISH_QTY, NIGHT_SYS_ANALYSIS, NIGHT_HAND_ANALYSIS, NIGHT_PROCESS_VALUE, DAY_USED, SUPPLY_TIME, TODAY_STOCK, YES_STOCK, TOTAL_PLAN, RUBBER_CODE, RUBBER_CAR_NUMBER, ORIGINAL_BRAND, ORIGINAL_BRAND_NUM, CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE, PUBLISH_SUCCESS_COUNT, NEWEST_PUBLISH_TIME, EXTRA_PLAN_FLAG, ORIGINAL_REMIND_FLAG, DEL_FLAG, REMARK, CREATE_BY, CREATE_TIME, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS, DATA_SOURCE, CLOSE_OUT_SPEC_FLAG) SELECT SEQ_XWYY_SCHEDULE.NEXTVAL AS ID, T.* FROM (
SELECT #{schedule.scheduleDate}, #{schedule.cd90BatchNo,jdbcType = VARCHAR}, #{schedule.batchNo,jdbcType = VARCHAR}, #{schedule.orderNo,jdbcType = VARCHAR}, #{schedule.bigRollCode,jdbcType = VARCHAR}, #{schedule.originalLineCode,jdbcType = VARCHAR}, #{schedule.originalLineQtyNum,jdbcType = VARCHAR}, #{schedule.machineId,jdbcType = VARCHAR}, #{schedule.dayPlanQty,jdbcType = DOUBLE}, #{schedule.dayPlanQtyNum,jdbcType = DOUBLE}, #{schedule.dayFinishQty,jdbcType = DOUBLE}, #{schedule.daySysAnalysis,jdbcType = VARCHAR}, #{schedule.dayHandAnalysis,jdbcType = VARCHAR}, #{schedule.dayProcessValue,jdbcType = VARCHAR}, #{schedule.nightPlanQty,jdbcType = DOUBLE}, #{schedule.nightPlanQtyNum,jdbcType = DOUBLE}, #{schedule.nightFinishQty,jdbcType = DOUBLE}, #{schedule.nightSysAnalysis,jdbcType = VARCHAR}, #{schedule.nightHandAnalysis,jdbcType = VARCHAR}, #{schedule.nightProcessValue,jdbcType = VARCHAR}, #{schedule.dayUsed,jdbcType = DOUBLE}, #{schedule.supplyTime,jdbcType = DOUBLE}, #{schedule.todayStock,jdbcType = DOUBLE}, #{schedule.yesStock,jdbcType = DOUBLE}, #{schedule.totalPlan,jdbcType = DOUBLE}, #{schedule.rubberCode,jdbcType = VARCHAR}, #{schedule.rubberCarNumber,jdbcType = DOUBLE}, #{schedule.originalBrand,jdbcType = VARCHAR}, #{schedule.originalBrandNum,jdbcType = DOUBLE}, #{schedule.cxClass1Plan,jdbcType = DOUBLE}, #{schedule.cxClass2Plan,jdbcType = DOUBLE}, #{schedule.cxClass3Plan,jdbcType = DOUBLE}, #{schedule.cxClass4Plan,jdbcType = DOUBLE}, #{schedule.cxClass5Plan,jdbcType = DOUBLE}, #{schedule.isRelease,jdbcType = VARCHAR}, #{schedule.publishSuccessCount,jdbcType = INTEGER}, #{schedule.newestPublishTime,jdbcType = DATE}, #{schedule.extraPlanFlag,jdbcType = VARCHAR}, #{schedule.originalRemindFlag,jdbcType = VARCHAR}, #{schedule.delFlag,jdbcType = VARCHAR}, #{schedule.remark,jdbcType = VARCHAR}, #{schedule.createBy,jdbcType = VARCHAR}, #{schedule.createTime}, #{schedule.markCloseOutTip,jdbcType = VARCHAR}, #{schedule.productionStatus,jdbcType = VARCHAR}, #{schedule.dataSource,jdbcType = VARCHAR}, #{schedule.closeOutSpecFlag,jdbcType = VARCHAR} FROM DUAL
) T

mapper.update:
UPDATE T_XWYY_AUTO_SCHEDULE_RECORD 
   SET DEL_FLAG = '1', 
       UPDATE_BY = #{createBy}, 
       UPDATE_TIME = #{createTime}
 WHERE schedule_date = #{scheduleDate}
   AND DEL_FLAG = '0'

MERGE INTO T_XWYY_SCHEDULE_RESULT a USING (
SELECT #{schedule.scheduleDate} schedule_Date, #{schedule.cd90BatchNo,jdbcType = VARCHAR} CD90_BATCH_NO, #{schedule.batchNo,jdbcType = VARCHAR} BATCH_NO, #{schedule.orderNo,jdbcType = VARCHAR} order_No, #{schedule.bigRollCode,jdbcType = VARCHAR} big_Roll_Code, #{schedule.originalLineCode,jdbcType = VARCHAR} ORIGINAL_LINE_CODE, #{schedule.originalLineQtyNum,jdbcType = VARCHAR} ORIGINAL_LINE_QTY_NUM, #{schedule.machineId,jdbcType = VARCHAR} machine_Id, #{schedule.dayPlanQty,jdbcType = DOUBLE} day_Plan_Qty, #{schedule.dayPlanQtyNum,jdbcType = DOUBLE} day_Plan_Qty_num, #{schedule.dayHandAnalysis,jdbcType = VARCHAR} day_Hand_Analysis, #{schedule.dayProcessValue,jdbcType = VARCHAR} DAY_PROCESS_VALUE, #{schedule.nightPlanQty,jdbcType = DOUBLE} night_Plan_Qty, #{schedule.nightPlanQtyNum,jdbcType = DOUBLE} night_Plan_Qty_num, #{schedule.nightHandAnalysis,jdbcType = VARCHAR} night_Hand_Analysis, #{schedule.nightProcessValue,jdbcType = VARCHAR} NIGHT_PROCESS_VALUE, #{schedule.yesStock,jdbcType = DOUBLE} YES_STOCK, #{schedule.todayStock,jdbcType = DOUBLE} TODAY_STOCK, #{schedule.dayUsed,jdbcType = DOUBLE} day_Used, #{schedule.dayOut,jdbcType = DOUBLE} DAY_OUT, #{schedule.fac2Class1Plan,jdbcType = DOUBLE} FAC2_CLASS1_PLAN, #{schedule.fac2Class2Plan,jdbcType = DOUBLE} FAC2_CLASS2_PLAN, #{schedule.fac2Class3Plan,jdbcType = DOUBLE} FAC2_CLASS3_PLAN, #{schedule.fac2TotalPlan,jdbcType = DOUBLE} FAC2_TOTAL_PLAN, #{schedule.fac5Class1Plan,jdbcType = DOUBLE} FAC5_CLASS1_PLAN, #{schedule.fac5Class2Plan,jdbcType = DOUBLE} FAC5_CLASS2_PLAN, #{schedule.fac5Class3Plan,jdbcType = DOUBLE} FAC5_CLASS3_PLAN, #{schedule.fac5TotalPlan,jdbcType = DOUBLE} FAC5_TOTAL_PLAN, #{schedule.totalPlan,jdbcType = DOUBLE} TOTAL_PLAN, #{schedule.rubberCode,jdbcType = VARCHAR} RUBBER_CODE, #{schedule.rubberCarNumber,jdbcType = DOUBLE} RUBBER_CAR_NUMBER, #{schedule.originalBrand,jdbcType = VARCHAR} ORIGINAL_BRAND, #{schedule.originalBrandNum,jdbcType = DOUBLE} ORIGINAL_BRAND_NUM, #{schedule.cxClass1Plan,jdbcType = DOUBLE} CX_CLASS1_PLAN, #{schedule.cxClass2Plan,jdbcType = DOUBLE} CX_CLASS2_PLAN, #{schedule.cxClass3Plan,jdbcType = DOUBLE} CX_CLASS3_PLAN, #{schedule.cxClass4Plan,jdbcType = DOUBLE} CX_CLASS4_PLAN, #{schedule.cxClass5Plan,jdbcType = DOUBLE} CX_CLASS5_PLAN, #{schedule.supplyTime,jdbcType = DOUBLE} supply_Time, #{schedule.isRelease,jdbcType = VARCHAR} is_Release, #{schedule.extraPlanFlag,jdbcType = VARCHAR} EXTRA_PLAN_FLAG, #{schedule.originalRemindFlag,jdbcType = VARCHAR} ORIGINAL_REMIND_FLAG, #{schedule.markCloseOutTip,jdbcType = VARCHAR} mark_Close_Out_Tip, #{schedule.remark,jdbcType = VARCHAR} remark, #{schedule.productionStatus,jdbcType = VARCHAR} production_Status, #{schedule.delFlag,jdbcType = VARCHAR} del_Flag, #{schedule.createBy,jdbcType = VARCHAR} create_By, #{schedule.createTime} create_Time, #{schedule.dataSource,jdbcType = VARCHAR} data_Source, #{schedule.closeOutSpecFlag,jdbcType = VARCHAR} CLOSE_OUT_SPEC_FLAG from dual
) b ON (a.schedule_date = b.schedule_date AND a.big_Roll_Code = b.big_Roll_Code AND a.machine_id = b.machine_id AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.day_Plan_Qty = b.day_Plan_Qty, a.day_Plan_Qty_Num = b.day_Plan_Qty_Num, a.night_Plan_Qty = b.night_Plan_Qty, a.night_Plan_Qty_Num = b.night_Plan_Qty_Num, a.YES_STOCK = b.YES_STOCK, a.TODAY_STOCK = b.TODAY_STOCK, a.day_Used = b.day_Used , a.DAY_OUT = b.DAY_OUT , a.ORIGINAL_LINE_CODE = b.ORIGINAL_LINE_CODE, a.ORIGINAL_LINE_QTY_NUM = b.ORIGINAL_LINE_QTY_NUM, a.FAC2_CLASS1_PLAN = b.FAC2_CLASS1_PLAN , a.FAC2_CLASS2_PLAN = b.FAC2_CLASS2_PLAN , a.FAC2_CLASS3_PLAN = b.FAC2_CLASS3_PLAN , a.FAC2_TOTAL_PLAN = b.FAC2_TOTAL_PLAN , a.FAC5_CLASS1_PLAN = b.FAC5_CLASS1_PLAN , a.FAC5_CLASS2_PLAN = b.FAC5_CLASS2_PLAN , a.FAC5_CLASS3_PLAN = b.FAC5_CLASS3_PLAN , a.FAC5_TOTAL_PLAN = b.FAC5_TOTAL_PLAN , a.total_Plan = b.total_Plan , a.RUBBER_CODE = b.RUBBER_CODE, a.RUBBER_CAR_NUMBER = b.RUBBER_CAR_NUMBER, a.ORIGINAL_BRAND = b.ORIGINAL_BRAND, a.ORIGINAL_BRAND_NUM = b.ORIGINAL_BRAND_NUM, a.REMARK = b.REMARK, a.mark_Close_Out_Tip = b.mark_Close_Out_Tip, a.production_status = b.production_status, a.update_by = b.create_By, a.update_time = b.create_By, a.data_Source = b.data_Source, a.CX_CLASS1_PLAN = b.CX_CLASS1_PLAN, a.CX_CLASS2_PLAN = b.CX_CLASS2_PLAN, a.CX_CLASS3_PLAN = b.CX_CLASS3_PLAN, a.CX_CLASS4_PLAN = b.CX_CLASS4_PLAN, a.CX_CLASS5_PLAN = b.CX_CLASS5_PLAN, a.supply_Time = b.supply_Time, a.CLOSE_OUT_SPEC_FLAG = b.CLOSE_OUT_SPEC_FLAG WHEN NOT MATCHED THEN INSERT (a.id,a.schedule_Date,a.batch_no,a.order_no,a.big_Roll_Code,a.machine_Id,a.ORIGINAL_LINE_CODE,a.ORIGINAL_LINE_QTY_NUM,a.day_Plan_Qty,a.day_Plan_Qty_Num,a.day_Hand_Analysis,a.DAY_PROCESS_VALUE,a.night_Plan_Qty,a.night_Plan_Qty_Num,a.night_Hand_Analysis,a.NIGHT_PROCESS_VALUE,a.yes_stock,a.today_stock,a.day_Used,a.DAY_OUT,a.FAC2_CLASS1_PLAN,a.FAC2_CLASS2_PLAN,a.FAC2_CLASS3_PLAN,a.FAC2_TOTAL_PLAN,a.FAC5_CLASS1_PLAN,a.FAC5_CLASS2_PLAN,a.FAC5_CLASS3_PLAN,a.FAC5_TOTAL_PLAN,a.total_Plan,a.RUBBER_CODE,a.RUBBER_CAR_NUMBER,a.ORIGINAL_BRAND,a.ORIGINAL_BRAND_NUM,a.is_release,a.EXTRA_PLAN_FLAG,a.ORIGINAL_REMIND_FLAG,a.mark_close_out_tip,a.remark,a.production_status,a.del_flag,a.create_by,a.create_time,a.data_Source,a.CX_CLASS1_PLAN,a.CX_CLASS2_PLAN,a.CX_CLASS3_PLAN,a.CX_CLASS4_PLAN,a.CX_CLASS5_PLAN,a.supply_Time,a.CLOSE_OUT_SPEC_FLAG) values (SEQ_XWYY_SCHEDULE.NEXTVAL,b.schedule_Date,b.batch_no,b.order_no,b.big_Roll_Code,b.machine_Id,b.ORIGINAL_LINE_CODE,b.ORIGINAL_LINE_QTY_NUM,b.day_Plan_Qty,b.day_Plan_Qty_Num,b.day_Hand_Analysis,b.DAY_PROCESS_VALUE,b.night_Plan_Qty,b.night_Plan_Qty_Num,b.night_Hand_Analysis,b.NIGHT_PROCESS_VALUE,b.yes_stock,b.today_stock,b.day_Used,b.DAY_OUT,b.FAC2_CLASS1_PLAN,b.FAC2_CLASS2_PLAN,b.FAC2_CLASS3_PLAN,b.FAC2_TOTAL_PLAN,b.FAC5_CLASS1_PLAN,b.FAC5_CLASS2_PLAN,b.FAC5_CLASS3_PLAN,b.FAC5_TOTAL_PLAN,b.total_Plan,b.RUBBER_CODE,b.RUBBER_CAR_NUMBER,b.ORIGINAL_BRAND,b.ORIGINAL_BRAND_NUM,b.is_release,b.EXTRA_PLAN_FLAG,b.ORIGINAL_REMIND_FLAG,b.mark_close_out_tip,b.remark,b.production_status,b.del_flag,b.create_by,b.create_time,b.data_Source,b.CX_CLASS1_PLAN,b.CX_CLASS2_PLAN,b.CX_CLASS3_PLAN,b.CX_CLASS4_PLAN,b.CX_CLASS5_PLAN,b.supply_Time,b.CLOSE_OUT_SPEC_FLAG)

