INSERT INTO T_XWYY_ASSIST_SCHEDULE (ID, schedule_DATE, CD90_BATCH_NO, BATCH_NO, ORDER_NO, BIG_ROLL_CODE, ORIGINAL_LINE_CODE, MACHINE_ID, DAY_PLAN_QTY, DAY_SYS_ANALYSIS, NIGHT_PLAN_QTY, NIGHT_SYS_ANALYSIS, DAY_USED, SUPPLY_TIME, TODAY_STOCK, YES_STOCK, TOTAL_PLAN, CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE, DEL_FLAG, CREATE_BY, CREATE_TIME, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS) SELECT SEQ_XWYY_SCHEDULE.NEXTVAL AS ID, T.* FROM (
SELECT #{schedule.scheduleDate}, #{schedule.cd90BatchNo,jdbcType = VARCHAR}, #{schedule.batchNo,jdbcType = VARCHAR}, #{schedule.orderNo,jdbcType = VARCHAR}, #{schedule.bigRollCode,jdbcType = VARCHAR}, #{schedule.originalLineCode,jdbcType = VARCHAR}, #{schedule.machineId,jdbcType = VARCHAR}, #{schedule.dayPlanQty,jdbcType = DOUBLE}, #{schedule.daySysAnalysis,jdbcType = VARCHAR}, #{schedule.nightPlanQty,jdbcType = DOUBLE}, #{schedule.nightSysAnalysis,jdbcType = VARCHAR}, #{schedule.dayUsed,jdbcType = DOUBLE}, #{schedule.supplyTime,jdbcType = DOUBLE}, #{schedule.todayStock,jdbcType = DOUBLE}, #{schedule.yesStock,jdbcType = DOUBLE}, #{schedule.totalPlan,jdbcType = DOUBLE}, #{schedule.cxClass1Plan,jdbcType = DOUBLE}, #{schedule.cxClass2Plan,jdbcType = DOUBLE}, #{schedule.cxClass3Plan,jdbcType = DOUBLE}, #{schedule.cxClass4Plan,jdbcType = DOUBLE}, #{schedule.cxClass5Plan,jdbcType = DOUBLE}, #{schedule.isRelease,jdbcType = VARCHAR}, #{schedule.delFlag,jdbcType = VARCHAR}, #{schedule.createBy,jdbcType = VARCHAR}, #{schedule.createTime}, #{schedule.markCloseOutTip,jdbcType = VARCHAR}, #{schedule.productionStatus,jdbcType = VARCHAR} FROM DUAL
) T

