MERGE INTO T_XWYY_SCHEDULE_RESULT a USING (
SELECT #{schedule.id} id, #{schedule.originalBrandNum,jdbcType = DOUBLE} ORIGINAL_BRAND_NUM, #{schedule.updateBy,jdbcType = VARCHAR} update_By, #{schedule.updateTime} update_Time from dual
) b ON (a.id = b.id ) WHEN MATCHED THEN UPDATE SET a.ORIGINAL_BRAND_NUM = b.ORIGINAL_BRAND_NUM, a.update_by = b.update_By, a.update_time = b.update_Time
